/**
 * @name Command injection from user input
 * @description Command execution with user-controlled input can lead to arbitrary command execution
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-taint-dotenv
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // CLI arguments, file content, or environment variables
    exists(API::Node apiNode |
      apiNode = API::moduleImport("sys").getMember("argv") or
      apiNode = API::moduleImport("click").getMember("argument").getACall().getReturn() or
      apiNode = API::moduleImport("click").getMember("option").getACall().getReturn()
    |
      source = apiNode.getAValueReachableFromSource()
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in file operations
 * @description Using user-controlled paths without validation can lead to unauthorized file access
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-dotenv
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // CLI arguments or function parameters
    exists(API::Node apiNode |
      apiNode = API::moduleImport("sys").getMember("argv") or
      apiNode = API::moduleImport("click").getMember(["argument", "option"]).getACall().getReturn()
    |
      source = apiNode.getAValueReachableFromSource()
    ) or
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fsa |
      sink = fsa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Environment variable injection
 * @description Setting environment variables with user-controlled names or values can lead to security issues
 * @kind path-problem
 * @problem.severity warning
 * @id py/env-injection-dotenv
 * @tags security
 *        external/cwe/cwe-454
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EnvInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // File content or user input
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("io").getMember("open").getACall() or
      call = API::builtin("open").getACall()
    |
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // os.environ assignments
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("environ").getMember(["__setitem__", "update"]).getACall()
    |
      sink in [call.getArg(0), call.getArg(1)]
    )
  }
}

module EnvInjectionFlow = TaintTracking::Global<EnvInjectionConfig>;
import EnvInjectionFlow::PathGraph

from EnvInjectionFlow::PathNode source, EnvInjectionFlow::PathNode sink
where EnvInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Environment variable injection from $@.", source.getNode(), "file content"
